/// Access a composite field route and describe its child type and source spellings.
///
/// Each eligible field has a nominal marker generated by the composite macro.
/// Use [`crate::field!`] to name a field or an arbitrarily nested route, such as
/// `field!(Composite::field::nested)`. The marker need not be named directly.
/// The child is the exact authored field type in the parent declaration scope.
/// Imported aliases and associated/generic child types retain Rust identity.
/// Ordinary state fields do not participate in field routes or capability lifting.
/// Without `program-image-execution`, legacy `#[loadable]` fields also stop route
/// traversal and capability lifting; their sections are loaded separately.
///
/// Use this trait in bounds on consumers of field routes. Implementations are
/// supplied by [`crate::composite`] and the generated route traversal.
pub trait Field<F> {
    /// The exact type of the final child selected by the route.
    type Child;
    /// Borrow the selected child for the lifetime of this composite borrow.
    fn get(&self) -> &Self::Child;
    /// Mutably borrow the selected child for the lifetime of this composite borrow.
    fn get_mut(&mut self) -> &mut Self::Child;
    /// Canonical name of the final field first, then its aliases in declaration order.
    const SOURCE: &'static [&'static str];
}
